//! Exact existing records plus seven independently derived cached FA packets.
use super::manifests::{self, AttentionCase as C, AttentionRole as R, AttentionStage as S};
use crate::vllm_cuda_qualification::cubin_manifests::ProjectionImage;
use cubecl::cuda::CubinKernelManifest;
use zerogravity_core::{Error, Result};

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub(crate) enum Role {
    AttentionOutput,
    BlockTableI32,
    CosSinSourcePrefix67,
    CuQI32,
    DummyCuKI32,
    Gate,
    K,
    KGamma,
    KScale,
    LseF32,
    OriginalKvState,
    OutInput,
    OutW,
    PackedQkv,
    PartialLseF32,
    PartialOF32,
    PositionsI64Pitch65,
    PrivateO,
    Projected,
    Q,
    QGamma,
    QkvInput,
    QkvW,
    SigmoidGate,
    SeqUsedI32,
    SlotsI64,
    VScale,
    Workspace,
}
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub(crate) enum Stage {
    Qkv,
    Qk,
    Kv,
    Fa,
    Sigmoid,
    Multiply,
    Out,
}
pub(crate) struct Packet {
    pub(crate) image: ProjectionImage,
    pub(crate) roles: Vec<Role>,
    pub(crate) manifest: CubinKernelManifest,
}
fn role(r: R) -> Role {
    match r {
        R::AttentionOutput => Role::AttentionOutput,
        R::BlockTableI32 => Role::BlockTableI32,
        R::CosSinSourcePrefix67 => Role::CosSinSourcePrefix67,
        R::CuQI32 => Role::CuQI32,
        R::DummyCuKI32 => Role::DummyCuKI32,
        R::Gate => Role::Gate,
        R::K => Role::K,
        R::KGamma => Role::KGamma,
        R::KScale => Role::KScale,
        R::LseF32 => Role::LseF32,
        R::OriginalKvState => Role::OriginalKvState,
        R::OutInput => Role::OutInput,
        R::OutW => Role::OutW,
        R::PackedQkv => Role::PackedQkv,
        R::PartialLseF32 => Role::PartialLseF32,
        R::PartialOF32 => Role::PartialOF32,
        R::PositionsI64Pitch65 => Role::PositionsI64Pitch65,
        R::PrivateO => Role::PrivateO,
        R::Projected => Role::Projected,
        R::Q => Role::Q,
        R::QGamma => Role::QGamma,
        R::QkvInput => Role::QkvInput,
        R::QkvW => Role::QkvW,
        R::SigmoidGate => Role::SigmoidGate,
        R::SeqUsedI32 => Role::SeqUsedI32,
        R::SlotsI64 => Role::SlotsI64,
        R::VScale => Role::VScale,
        R::Workspace => Role::Workspace,
    }
}
fn wrap(p: manifests::AttentionLaunch) -> Packet {
    Packet {
        image: p.image,
        roles: p.roles.iter().copied().map(role).collect(),
        manifest: p.manifest,
    }
}
// Actual ROOT metadata recipe; no mathematical operands or reference tensor.
const CACHED_FA: [&str; 7] = [
    "",
    "",
    "",
    "",
    "",
    "",
    "",
];
fn literal(s: &str) -> Result<Vec<u8>> {
    if s.len() != 944 {
        return Err(Error::State(
            "canonical cached FA complete472 byte recipe".into(),
        ));
    }
    s.as_bytes()
        .chunks_exact(2)
        .map(|pair| {
            let nibble = |x: u8| match x {
                b'0'..=b'9' => Ok(x - b'0'),
                b'a'..=b'f' => Ok(x - b'a' + 10),
                _ => Err(Error::State("fixed FA hex".into())),
            };
            Ok(nibble(pair[0])? * 16 + nibble(pair[1])?)
        })
        .collect()
}
pub(crate) fn cached_packets(base: usize, stage: Stage) -> Result<Vec<Packet>> {
    if !(47..=53).contains(&base) {
        return Err(Error::Unsupported(
            "canonical cached FA bases47..53 only".into(),
        ));
    }
    let old = match stage {
        Stage::Qkv => S::Qkv,
        Stage::Qk => S::Qk,
        Stage::Kv => S::Kv,
        Stage::Fa => S::Fa,
        Stage::Sigmoid => S::Sigmoid,
        Stage::Multiply => S::Multiply,
        Stage::Out => S::Out,
    };
    let mut out = manifests::launches(C::CachedOneAt1, old)
        .into_iter()
        .map(wrap)
        .collect::<Vec<_>>();
    if stage == Stage::Fa {
        if out.len() != 1 || out[0].manifest.parameters.len() != 1 {
            return Err(Error::State(
                "canonical cached FA original record count".into(),
            ));
        }
        out[0].manifest.parameters[0].template = literal(CACHED_FA[base - 47])?;
    }
    Ok(out)
}
pub(crate) fn prefill_packets(stage: Stage) -> Result<Vec<Packet>> {
    use super::canonical47_packets::Role as F;
    Ok(match stage {
        Stage::Qk | Stage::Kv | Stage::Fa => {
            let index = match stage {
                Stage::Qk => 0,
                Stage::Kv => 1,
                _ => 2,
            };
            let p = super::canonical47_packets::packets_with_fa(true)?
                .into_iter()
                .nth(index)
                .ok_or_else(|| Error::State("canonical initial47 attention packet".into()))?;
            let roles = p
                .roles
                .into_iter()
                .map(|r| match r {
                    F::Packed => Role::PackedQkv,
                    F::Q => Role::Q,
                    F::K => Role::K,
                    F::Gate => Role::Gate,
                    F::QGamma => Role::QGamma,
                    F::KGamma => Role::KGamma,
                    F::Rotary => Role::CosSinSourcePrefix67,
                    F::Positions => Role::PositionsI64Pitch65,
                    F::Cache => Role::OriginalKvState,
                    F::Slots => Role::SlotsI64,
                    F::KScale => Role::KScale,
                    F::VScale => Role::VScale,
                    F::O => Role::AttentionOutput,
                    F::Lse => Role::LseF32,
                    F::CuQ => Role::CuQI32,
                    F::DummyCuK => Role::DummyCuKI32,
                    F::SeqUsed => Role::SeqUsedI32,
                    F::Table => Role::BlockTableI32,
                })
                .collect();
            vec![Packet {
                image: p.image,
                roles,
                manifest: p.manifest,
            }]
        }
        Stage::Sigmoid | Stage::Multiply => {
            let which = usize::from(stage == Stage::Multiply);
            let (image, manifest) = super::canonical47_layer3_packets::packets()?
                .into_iter()
                .nth(which)
                .unwrap();
            let roles = if which == 0 {
                vec![Role::SigmoidGate, Role::Gate]
            } else {
                vec![Role::OutInput, Role::AttentionOutput, Role::SigmoidGate]
            };
            vec![Packet {
                image,
                roles,
                manifest,
            }]
        }
        _ => {
            return Err(Error::State(
                "initial47 QKV/Out use actual source projection factories".into(),
            ));
        }
    })
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn cached_all_seven_complete_packets_change_only_observed_fields() {
        for base in 47..=53 {
            let p = cached_packets(base, Stage::Fa).unwrap().remove(0);
            let b = &p.manifest.parameters[0].template;
            assert_eq!(b.len(), 472);
            assert_eq!(&b[466..], &[12, 59, 0, 0, 0, 0]);
            assert_eq!(i32::from_le_bytes(b[180..184].try_into().unwrap()), 4);
            assert_eq!(
                i32::from_le_bytes(b[184..188].try_into().unwrap()),
                (base + 1) as i32
            );
            assert_eq!(p.manifest.bindings[0].bytes, 4096);
            assert_eq!(p.manifest.bindings[2].bytes, 32);
            assert_eq!(p.manifest.grid, [1, 1, 2]);
        }
        for b in [0, 1, 46, 54, 66] {
            assert!(cached_packets(b, Stage::Fa).is_err());
        }
    }
}
